package com.cookly.servicios;
import com.cookly.dto.*; import com.cookly.repositorios.RepositorioReceta; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; import java.util.stream.*;
@Service public class ServicioReceta { private final RepositorioReceta recetas; public ServicioReceta(RepositorioReceta r){recetas=r;} @Transactional(readOnly=true) public List<RecomendacionReceta> menuExpress(SolicitudMenuExpress solicitud){var disponibles=solicitud.ingredientes().stream().map(x->x.trim().toLowerCase()).collect(Collectors.toSet());return recetas.findAll().stream().map(r->{var requeridos=r.getIngredientes().stream().map(i->i.getNombre().toLowerCase()).collect(Collectors.toSet());var faltantes=requeridos.stream().filter(x->!disponibles.contains(x)).sorted().toList();int porcentaje=requeridos.isEmpty()?0:(int)Math.round(100.0*(requeridos.size()-faltantes.size())/requeridos.size());Integer minutos=r.getMinutosPreparacion()==null?null:r.getMinutosPreparacion().intValue();return new RecomendacionReceta(r.getId(),r.getNombre(),porcentaje,faltantes,minutos);}).filter(x->x.porcentajeCoincidencia()>0).sorted(Comparator.comparing(RecomendacionReceta::porcentajeCoincidencia).reversed().thenComparing(x->x.ingredientesFaltantes().size()).thenComparing(RecomendacionReceta::minutosPreparacion,Comparator.nullsLast(Comparator.naturalOrder()))).limit(30).toList();} }
